src=base/'source'
receipts=[]
def run(args,name,cwd=None):
 p=subprocess.run(args,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 (base/(name+'.log')).write_bytes(p.stdout)
 receipts.append({'argv':args,'cwd':str(cwd or base),'exit_code':p.returncode,'log':name+'.log','sha256':hashlib.sha256(p.stdout).hexdigest()})
 (base/'setup-commands.json').write_text(json.dumps(receipts,indent=2)+'\n')
 print(json.dumps(receipts[-1]),flush=True)
 if p.returncode: print(p.stdout.decode(errors='replace'));raise SystemExit(p.returncode)
